// Content generated by scripts/build_*.py: books, exercises, notebooks.
import { useEffect, useState } from "react";

export type Topic = { id: string; idx: number; title: string; titleHtml: string; minutes: number; heads: string[];
  search: string; hasCode: boolean; figs: number; book: string; part: string };
export type Book = { id: string; title: string; icon: string; parts: { title: string; topics: Topic[] }[] };
export type Exercise = { id: string; track: string; title: string; level: number; prompt: string; starter: string;
  solution: string; tests: string; hints: string[]; topic: string };
export type Notebook = { file: string; title: string; emoji: string; kind: "interactive" | "code" | "mine"; desc: string;
  topic: string; group: string; mine?: boolean };
export type Data = { books: Book[]; macros: Record<string, string>; exercises: Exercise[];
  notebooks: Notebook[]; topics: Map<string, Topic>; order: string[] };

/** Learning paths: the sidebar shows one at a time. */
/** `icon` is an emoji for plain-text places (dropdowns); `ic` + `color` drive the sidebar and dashboard. */
export type Path = { id: string; icon: string; ic: "target" | "cpu" | "layers" | "shield"; color: string; title: string; long: string; books: string[] };
export const PATHS: Path[] = [
  { id: "rl", icon: "🎮", ic: "target", color: "#7c5cf6", title: "RL", long: "Reinforcement Learning", books: ["rl", "rlenv"] },
  { id: "llm", icon: "🧠", ic: "cpu", color: "#2f7bf6", title: "LLMs", long: "Large Language Models", books: ["llm", "post"] },
  { id: "sd", icon: "🏗️", ic: "layers", color: "#0f9f8f", title: "Systems", long: "System Design & Interviews", books: ["sd", "dsa"] },
  { id: "safety", icon: "🛡️", ic: "shield", color: "#e11d48", title: "Safety", long: "AI Safety", books: ["safety"] },
];
export const pathOf = (topicId: string) => PATHS.find((p) => p.books.includes(topicId.split(":")[0]))?.id ?? "rl";
export const pathTopicIds = (d: Data, pathId: string) => {
  const p = PATHS.find((x) => x.id === pathId) ?? PATHS[0];
  return d.order.filter((id) => p.books.includes(id.split(":")[0]));
};

let cache: Promise<Data> | null = null;
const get = (p: string) => fetch(p).then((r) => { if (!r.ok) throw new Error(`${p}: ${r.status}`); return r.json(); });

export function loadData(): Promise<Data> {
  cache ??= Promise.all([get("content/catalog.json"), get("content/exercises.json"),
                         get("content/notebooks.json")]).then(([cat, exercises, notebooks]) => {
    const topics = new Map<string, Topic>(), order: string[] = [];
    for (const b of cat.books as Book[])
      for (const p of b.parts)
        for (const t of p.topics) {
          t.book = b.id; t.part = p.title;
          topics.set(t.id, t); order.push(t.id);
        }
    return { books: cat.books, macros: cat.macros, exercises, notebooks, topics, order };
  });
  return cache;
}

export function useData() {
  const [d, setD] = useState<Data | null>(null);
  const [err, setErr] = useState("");
  useEffect(() => { loadData().then(setD, (e) => setErr(String(e))); }, []);
  return { data: d, error: err };
}

export const topicHtml = (id: string) => {
  const [book, idx] = id.split(":");
  return fetch(`content/${book}/${idx}.html`).then((r) => r.text());
};

const has = (t: Topic, term: string) => {
  const q = term.toLowerCase();
  return t.title.toLowerCase().includes(q) || t.heads.some((h) => h.toLowerCase().includes(q));
};

export function relatedExercises(t: Topic, d: Data) {
  return d.exercises.filter((e) => e.topic && has(t, e.topic)).slice(0, 4);
}
export function relatedNotebooks(t: Topic, list: Notebook[]) {
  return list.filter((n) => n.kind !== "code" && n.topic && has(t, n.topic)).slice(0, 3);
}

// Live notebook list from ~/.study-quest/notebooks (desktop app), or the bundled manifest in a browser.
let nbCache: Notebook[] | null = null;
const nbSubs = new Set<(n: Notebook[]) => void>();
export async function refreshNotebooks(fallback: Notebook[]) {
  const { inTauri, call } = await import("./tauri");
  try { nbCache = inTauri() ? await call<Notebook[]>("list_notebooks") : fallback; }
  catch { nbCache = fallback; }
  nbSubs.forEach((f) => f(nbCache!));
  return nbCache;
}
export function useNotebooks(d: Data) {
  const [list, setList] = useState<Notebook[]>(nbCache ?? d.notebooks);
  useEffect(() => {
    nbSubs.add(setList);
    if (!nbCache) refreshNotebooks(d.notebooks);
    return () => { nbSubs.delete(setList); };
  }, [d]);
  return list;
}
export const GROUP_ORDER = ["My notebooks", "Reinforcement Learning", "Transformers & LLMs", "Inference", "Math & Optimisation",
  "Probability & Statistics", "Agents & Evals", "Other"];
export function topicsFor(term: string, d: Data) {
  return d.order.map((id) => d.topics.get(id)!).filter((t) => has(t, term)).slice(0, 4);
}
